import sys
import os
import re
import threading

if sys.version_info.major == 3:
    from hran_elementmanager2g import ssh_client
else:
    import ssh_client
from time import sleep
from hran_elementmanager2g.utils.constants import (DEFAULT_BTS_IP, DEFAULT_PASSWORD, BTS_MNG_LOCATION,
                                                   BTS_MNG_JAVA_LOCATION, BTS_MNG_DIR, BTS_MNG_CLI_PROMPT)


class BTSManagerCLI(object):
    """
    Class used for interacting with 2G BTS Manger through CLI
    It will use a SSH session to the ElementManager2G PC in order to start the CLI Java process
    """

    def __init__(self, host, ssh_user, ssh_password, remote_working_dir, local_working_dir, board_type, gsm_load):
        os.path.normpath(BTS_MNG_LOCATION)
        self.bts_mng_location = '{}/{}'.format(BTS_MNG_LOCATION, BTS_MNG_DIR)
        self.java_location = '{}/{}'.format(BTS_MNG_LOCATION, BTS_MNG_JAVA_LOCATION)
        self.latest_bts_mng_location = None
        self.ssh_conn = None
        self.host = host
        self.ssh_user = ssh_user
        self.ssh_password = ssh_password
        self.remote_working_dir = remote_working_dir
        self.local_working_dir = local_working_dir
        self.board_type = board_type
        self.miv_version = None
        self.file_to_transfer = None
        self.all_dump = ''
        self.reading_thread_active = False
        self.working_dir_initial = []
        self.working_dir_final = []
        self.gsm_load = gsm_load
        self.dump_cli_thdread = None

    def __del__(self):
        self.close_ssh_connection()

    def open_ssh_and_build_channel(self):
        try:
            self.ssh_conn = ssh_client.SshClient(host=self.host, ssh_user=self.ssh_user, ssh_password=self.ssh_password,
                                                 connect=True)
            self.working_dir_initial = self._get_working_dir_content()
            self.ssh_conn.ssh_build_channel()
        except:
            return False
        return True

    def teardown_btsm_manager_cli(self):
        try:
            self.dump_cli_thread_if_alive()
        except:
            self.close_ssh_connection()
            return False
        try:
            self.close_ssh_connection()
        except:
            return False

        return True

    def dump_cli_thread_if_alive(self):
        print('INFO: Dump cli thread')
        self._stop_dump_btssm_cli_thread()

    def close_ssh_connection(self):
        print('INFO: Closing SSH connection')
        try:
            self.ssh_conn.ssh_close_channel()
            self.ssh_conn.ssh_close_connection()
            print('INFO: SSH connection successfully closed!')
        except:
            print('INFO: Failed to properly close SSH connection!')
            return False
        return True

    def check_BTS_Mng(self):
        if not self._check_path_existance(self.bts_mng_location) or not self._check_path_existance(self.java_location):
            return False
        # change dir
        self._ssh_change_dir(self.bts_mng_location)
        self.ssh_conn.ssh_write_cmd_on_channel('ls -t', 1)
        resp = self.ssh_conn.ssh_read_from_channel(1024).decode("utf-8")
        a = re.split(r"\s+", resp)
        b = [i for i in a if '2G_BTSManager' in i]
        if len(b) > 0:
            last_site_mng = b[0]
        else:
            print('ERROR: no 2G BTS Site Manager found installed in {}'.format(self.bts_mng_location))
            return False
        self.latest_bts_mng_location = '{}/{}'.format(self.bts_mng_location, last_site_mng)
        print('INFO: Latest installed 2G BTS Site Manager detected: {}'.format(self.latest_bts_mng_location))
        return True

    def open_BTS_Mng_cli(self):
        if not self.check_BTS_Mng():
            print('ERROR: Error at checking 2G BTS Site Manager'.format(self.bts_mng_location))
            return False
        if not self._build_BTS_Mng_open_cli_command():
            print('ERROR: Error at building open cli command!')
            return False
        self.ssh_conn.ssh_write_cmd_on_channel(self.open_cli_cmd, 2)
        return True

    def close_BTS_Mng_cli(self):
        self.ssh_conn.ssh_write_cmd_on_channel('EXIT', 2)
        self.ssh_conn.ssh_write_cmd_on_channel('\x03', 2)
        return True

    def open_BTS_Mng_cli_and_prepare_action_on_cli(self):
        if not self.open_ssh_and_build_channel():
            print("ERROR: Error at opening ssh channel")
            return False
        if not self.open_BTS_Mng_cli():
            print("ERROR: Error at opening BTS Mng Cli")
            return False
        self._start_dump_btssm_cli_thread(BTS_MNG_CLI_PROMPT)
        for i in range(60):
            sleep(1)
            # Starting CLI should not take more than 1 min
            if not self.reading_thread_active:
                self._stop_dump_btssm_cli_thread()
                break
        else:
            self._stop_dump_btssm_cli_thread()
            print("ERROR: Timeout exceeded for prompt {} appearance (>1 minute)!".format(BTS_MNG_CLI_PROMPT))
            return False
        return True

    def fetch_snapshot(self, timeout):
        self.ssh_conn.ssh_write_cmd_on_channel(
            'FETCH SNAPSHOT {}'.format(self._cyg_path_to_win_path(self.remote_working_dir)), 2)
        self._start_dump_btssm_cli_thread('Result: Successful')
        for i in range(timeout):
            # Snapshot collection should not take more than 30 mins
            sleep(1)
            if not self.ssh_conn.is_connected():
                print("INFO: At second no {} ssh conn is dropped!".format(i))
            if i > 1200:
                # Intermediate check after 1200 seconds
                if '* Fetching' not in self.all_dump:
                    self._stop_dump_btssm_cli_thread()
                    self.reading_thread_active = False
                    print("ERROR: Fetching snapshot didn't start in first 20 mins!")
                    return False
            if not self.reading_thread_active:
                print("INFO: Snapshot successfully saved!")
                self._stop_dump_btssm_cli_thread()
                break
        else:
            self._stop_dump_btssm_cli_thread()
            print("ERROR: Timeout exceeded for saving Snapshot (> {} seconds)!".format(timeout))
            return False
        if self.sftp_transfer_zip_file_from_remote('.zip', 'Slave_GSM_snapshot_CLI.zip'):
            print("INFO: Snapshot succesfully transfered on local machine at {}".format(self.local_working_dir))
            return True
        else:
            print("ERROR: Could not properly transfer Snapshot on local machine!")
            return False

    def sftp_transfer_zip_file_from_remote(self, file_type=None, desired_file_name=None):
        self.working_dir_final = self._get_working_dir_content()
        if desired_file_name and desired_file_name in self.working_dir_final:
            print("INFO: Removing old {} from working dir!".format(desired_file_name))
            self.ssh_conn.ssh_send_cmd_and_return_output(
                'rm -R {}/{}'.format(self.remote_working_dir, desired_file_name))
        new_content = [i for i in self.working_dir_final if i not in self.working_dir_initial]
        if len(new_content) == 0:
            print("ERROR: Cannot identify new content in the remote working dir. Content: {}".format(
                self.working_dir_final))
            return False
        elif len(new_content) > 1:
            print("ERROR: Too much new content found in the remote working dir. Content: {}".format(
                self.working_dir_final))
            return False
        else:
            self.file_to_transfer = new_content[0].strip()
        if file_type and file_type not in self.file_to_transfer:
            print("ERROR: File to transfer: {} is not the desired type: {}".format(self.file_to_transfer, file_type))
            return False
        if desired_file_name:
            print("INFO: Renaming {} to {}!".format(self.file_to_transfer, desired_file_name))
            cmd = 'mv {0}/{1} {0}/{2}'.format(self.remote_working_dir, self.file_to_transfer, desired_file_name)
            self.ssh_conn.ssh_send_cmd_and_return_output(cmd)
            self.file_to_transfer = desired_file_name
        print("INFO: Transfering file {}/{}".format(self.remote_working_dir, self.file_to_transfer))
        try:
            self.ssh_conn.transfer_file_from_remote_ssh_host \
                (cwd=self.remote_working_dir, \
                 remote_filename='{}/{}'.format(self.remote_working_dir, self.file_to_transfer), \
                 local_filename='{}/{}'.format(self.local_working_dir, self.file_to_transfer))
            return True
        except:
            print("ERROR: Could not properly transfer file {}/{} on local machine!".format(self.remote_working_dir,
                                                                                           self.file_to_transfer))
            return False

    def _check_path_existance(self, path):
        self.ssh_conn.ssh_write_cmd_on_channel('ls {}'.format(path), 2)
        resp = self.ssh_conn.ssh_read_from_channel(1024).decode("utf-8")
        if 'No such file or directory' not in resp:
            return True
        else:
            return False

    def _ssh_change_dir(self, dir):
        self.ssh_conn.ssh_write_cmd_on_channel('cd {}'.format(dir), 1)
        sleep(1)
        resp = self.ssh_conn.ssh_read_from_channel(-1).decode("utf-8")
        if 'No such file or directory' not in resp:
            return True
        else:
            print("ERROR: Could not change dir to {}".format(dir))
            return False

    def _build_BTS_Mng_open_cli_command(self):

        use_miv = False
        if self.board_type not in ['ME', 'GF']:
            print("ERROR: Board type provided not supported: {}".format(self.board_type))
            return False
        xml_file = 'cl_Multiradio10.xml' if self.board_type == 'GF' else 'cl_Multiradio.xml'
        regex_rel = r'BTSR(\d{2})' if self.board_type == 'GF' else r'BTSM(\d{1})'
        gsm_rel_with_miv_list = ['BTSR19'] if self.board_type == 'GF' else ['BTSM9']
        try:
            gsm_rel = re.search(regex_rel, self.gsm_load).group(0)
            print("INFO: Detected GSM Rel: {}".format(gsm_rel))
            if gsm_rel in gsm_rel_with_miv_list:
                use_miv = True
        except:
            use_miv = True

        if use_miv:
            if not self._check_miv_version(xml_file):
                print("ERROR: Error at detecting MIV version for GF command!")
                return False
            else:
                cmd_target = 'WP=BTS,HOST={},PSW={},MIV={},POLL_TIME=10'.format(DEFAULT_BTS_IP, DEFAULT_PASSWORD,
                                                                                self.miv_version)
        else:
            cmd_target = 'WP=BTS,HOST={},PSW={},POLL_TIME=10'.format(DEFAULT_BTS_IP, DEFAULT_PASSWORD)

        self._ssh_change_dir(self.latest_bts_mng_location)
        security_policy = './config/encrypted_ualc.policy'
        security_login_config = './config/sample_jaas.config'
        lib_path = './lib'
        em_jar_path = 'lib/EM.jar'
        self.open_cli_cmd = '{} \
-Djava.security.policy=={} \
-Djava.security.auth.login.config=={} \
-Duitheme.OceanTouch=true \
-DOceanTouch.autoCreateFocusedIcon=false \
-Xmx1024m \
-Djava.library.path={} \
-jar {} \
--mode {} -target {} -verbose\
'.format(self.java_location, security_policy, security_login_config, lib_path, em_jar_path, self.board_type, cmd_target)
        print("INFO: Opening BTS Mng CLI command: {}".format(self.open_cli_cmd))
        return True

    def _start_dump_btssm_cli_thread(self, stop_condition):
        self.stop_cli_dump = threading.Event()
        self.dump_cli_thdread = threading.Thread(target=self._read_from_btssm_cli, args=(stop_condition,))
        self.dump_cli_thdread.setDaemon(True)
        self.dump_cli_thdread.start()
        print("INFO: Dump btssm CLI thread succesfully started!")

    def _stop_dump_btssm_cli_thread(self):
        self.stop_cli_dump.set()
        self.dump_cli_thdread.join(3.0)
        pass

    def _read_from_btssm_cli(self, stop_condition):
        self.reading_thread_active = True
        while not stop_condition in self.all_dump and not self.stop_cli_dump.is_set():
            self.current_resp = self.ssh_conn.ssh_read_from_channel(1024).decode("utf-8")
            if self.current_resp:
                self.all_dump += self.current_resp
                print(self.current_resp)
        self.reading_thread_active = False

    def _cyg_path_to_win_path(self, cygpath):
        return cygpath.replace('/cygdrive/c', 'C:\\').replace('/', '\\')

    def _get_working_dir_content(self):
        return self.ssh_conn.ssh_send_cmd_and_return_output('ls {}'.format(self.remote_working_dir))

    def _empty_remote_working_dir(self):
        self._ssh_change_dir(self.remote_working_dir)
        self.ssh_conn.ssh_write_cmd_on_channel('ls', 1)
        resp = self.ssh_conn.ssh_read_from_channel(1024).decode("utf-8")
        a = re.split(r'\s+', resp)
        b = [i for i in a if 'zip' in i]
        if len(b) == 0:
            print("INFO: Dir {} is already empty of zip files!".format(self.remote_working_dir))
            return True
        self.ssh_conn.ssh_write_cmd_on_channel('rm -R {}/*'.format(self.remote_working_dir), 5)
        return True

    def _check_miv_version(self, xml_file_to_check):
        if not self.latest_bts_mng_location:
            print("ERROR: Could not check MIV version. Latest Bts Mng location not identified!")
            return False
        resp = self.ssh_conn.ssh_send_cmd_and_return_output(
            'grep -A 2 \'<interfaceVersion interfaceType=\"miv\">\' {}/{}'.format(self.latest_bts_mng_location,
                                                                                  xml_file_to_check))
        if len(resp) !=3:
            print("ERROR: Could not detect MIV version in {}!".format(xml_file_to_check))
            return False
        miv_major, miv_minor = None, None
        for i in resp:
            if 'major value' in i:
                miv_major = re.search(r'\d+', i).group(0)
            elif 'minor value' in i:
                miv_minor = re.search(r'\d+', i).group(0)
        if miv_minor and miv_major:
            self.miv_version = '{}.{}'.format(miv_major, miv_minor)
            return True
        else:
            print("ERROR: Error at detecting MIV major/minor version!")
            return False